package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Opens the claim, recording the signed-in user who opened it. */
public class OpenClaim {
    public void apply(@Val Claim claim, HttpServletRequest request) throws InvalidClaimStatusException {
        claim.moveTo(ClaimStatus.OPEN);
        claim.setOpenedBy(Audit.user(request));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * A claim's audit record: its person, its amount as the screen shows it, its date, and its number
 * when it has one (a voided claim's line carries the number it had).
 */
final class ClaimAudit {
    private ClaimAudit() {}

    static String line(String event, Sheet sheet, String user, Person person, Claim claim) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + sheet.id() + " by=" + user + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getAuditNumber() == null ? "" : " number=" + claim.getAuditNumber());
    }
}

